const DEFAULT_COLUMN_MAPPING: ColumnMapping = {
  prompt: ['prompt', 'question', 'user_prompt', 'input', 'message', 'query'],
  expectedOutput: ['expected', 'expected_output', 'answer', 'response'],
  intent: ['intent', 'expected_intent', 'purpose', 'goal'],
  category: ['category', 'type', 'topic', 'domain'],
  difficulty: ['difficulty', 'level', 'complexity'],
  keywords: ['keywords', 'expected_keywords', 'key_terms'],
};

private detectColumnMappings(headers: string[]) {
  const mapping: Record<string, string | undefined> = {};
  // Normalize every header into the alias space: lowercase, and collapse any non-alphanumeric run to '_'.
  const normalized = headers.map(h => h.toLowerCase().replace(/[^a-z0-9]/g, '_'));
  for (const [field, aliases] of Object.entries(DEFAULT_COLUMN_MAPPING)) {
    for (let i = 0; i < headers.length; i++) {
      // FIRST matching header wins (break) — with two prompt-like columns the leftmost is chosen.
      // Store the ORIGINAL header string, since that's what indexes into each raw row later.
      if (aliases.includes(normalized[i])) { mapping[field] = headers[i]; break; }
    }
  }
  return mapping;
}

private buildDataset(name: string, sourcePath: string, originalRowCount: number, prompts: UserPrompt[]): GoldenDataset {
  // Dedupe categories via Set; filter(Boolean) drops rows with no category so a blank cell isn't a category.
  const categories = [...new Set(prompts.map(p => p.category).filter(Boolean) as string[])];
  const difficulties: Record<string, number> = {};
  for (const prompt of prompts) {
    // Frequency tally: seed each new difficulty bucket at 0 the first time it's seen.
    if (prompt.difficulty) difficulties[prompt.difficulty] = (difficulties[prompt.difficulty] || 0) + 1;
  }
  return {
    // Date.now() makes each conversion separately named and non-overwriting — a re-run never clobbers the last dataset.
    id: `dataset-${name}-${Date.now()}`,
    name: `Golden Dataset: ${name}`,
    version: '1.0.0',
    timestamp: new Date().toISOString(),
    // originalRowCount preserved for audit: originalRowCount - totalPrompts = rows dropped for empty prompt text.
    source: { type: 'excel', path: sourcePath, originalRowCount },
    prompts,
    metadata: { totalPrompts: prompts.length, categories, difficulties, tags: [] },
  };
}

private async getModelResponse(prompt: string, model?: string): Promise<string> {
  // Optional model arg targets a specific backing model; omitted => the environment default.
  const client = this.getAppClient(model);
  try {
    const result = await client.chat(prompt);
    this.log(`  Response received in ${result.telemetry.messageResponseTime}ms`);
    return result.response.answer;
  } catch (error: any) {
    // Re-throw with context — never swallow into an empty string, which would score as a real (bad) answer.
    throw new Error(`Failed to get model response: ${error.message}`);
  }
}

private async evaluateResponse(prompt: UserPrompt, response: string) {
  const bundle: EvalBundle = {
    id: `eval-${prompt.id}-${Date.now()}`,
    prompt: prompt.prompt,
    response,
    timestamp: new Date().toISOString(),
    // expected_output makes quality scoring reference-based (compared to a gold answer) rather than open-ended.
    expected_output: prompt.expectedOutput,
    evaluation_config: {
      // Three independent checks in one call: deterministic PII + safety gates, plus an LLM-scored quality rating.
      enable_pii_detection: true,
      enable_safety_check: true,
      enable_quality_score: true,
      // Bar the quality score must clear service-side — separate from the PASS/WARNING/FAIL mapping applied later.
      quality_threshold: 0.75,
    } as EnhancedEvalConfig,
  };
  const result = await sendEval(bundle);
  // Collapse pii_findings to just its length — the verdict only needs WHETHER PII was found, not the findings.
  return { overall: result.overall, gates: result.gates, scores: result.scores,
           piiFindings: result.pii_findings.length };
}

private buildCombinedScore(evalResult, rubricScores, rawResult): CombinedEvalScore {
  // AND the two deterministic gates; ?.passed means a missing gate reads as falsy instead of throwing.
  const gatesPassed = evalResult.gates.pii?.passed && evalResult.gates.safety?.passed;

  const rubricScore = rubricScores.averageNormalized;
  const deepevalAvg = /* average of teacher_quality, relevancy, coherence */ null;

  // If the LLM-quality half didn't run (null), fall back to rubric alone; else weighted blend of the two.
  let aggregateScore = deepevalAvg === null
    ? rubricScore
    : rubricScore * DEFAULT_SCORING_WEIGHTS.rubric + deepevalAvg * DEFAULT_SCORING_WEIGHTS.deepeval;
  aggregateScore = Math.round(aggregateScore * 1000) / 1000;

  // Hard veto: a failed PII/safety gate forces FAIL no matter how high the score — score can't outrank a gate.
  const hardFail = !gatesPassed;
  const verdict: Verdict = hardFail ? 'FAIL' : computeVerdict(aggregateScore);

  return { rubricScores, gates: evalResult.gates, gatesPassed, aggregateScore, verdict, hardFail };
}
